function readCharges4(){let laborAuto=0;for(let i=0;i<6;i++)laborAuto+=(number('ln'+i)||0)*(number('lr'+i)||0)*(number('lt'+i)||0);return {trip:value('fTrip'),truck:number('fTruck')||0,laborAuto,labor:value('fLaborOverride')===''?laborAuto:number('fLaborOverride'),laborBasis:value('fLaborBasis'),laborRange:value('fLaborRange'),clean:(number('fCleanRate')||0)*(number('fCleanBags')||0),plastic:number('fPlastic')||0,sack:number('fSack')||0,advance:number('fAdvance')||0};}
