function splits4(amount,outgoing=false){const splits=[...document.querySelectorAll('.req-split')].map(el=>({account:value('sa'+el.dataset.i),amount:number('sm'+el.dataset.i)}));if(splits.some(s=>!Number.isFinite(s.amount)||s.amount<0||!aOpts().some(a=>a[0]===s.account))||Math.abs(splits.reduce((n,s)=>n+s.amount,0)-amount)>.001){error('ငွေခွဲပမာဏ စုစုပေါင်းသည် ငွေရှင်းပမာဏနှင့် တူရမည်။');return null;}if(outgoing){const sums={};splits.forEach(s=>sums[s.account]=(sums[s.account]||0)+s.amount);if(Object.entries(sums).some(([a,n])=>n>bal(a)+.001)){error('ရွေးထားသော ငွေသိမ်းရာတွင် ငွေမလောက်ပါ။');return null;}}return splits.filter(s=>s.amount>0);}
function takeLot4(l,qty){const before=l.qty,cost=qty*(Number(l.cost)||0);l.qty=Math.max(0,l.qty-qty);l.bags=Math.max(0,(l.bags||0)*(l.qty/before));if(l.packageViss)l.packageCount=l.qty/l.packageViss;return cost;}
