 if(!rows.length||rows.some(x=>!x.product||!(x.qty>0)||!(x.price>0)))return error('ကုန်၊ အလေးချိန်နှင့် ဈေးကို မှန်ကန်စွာထည့်ပါ။');if(new Set(rows.map(x=>x.product)).size!==rows.length)return error('ကုန်တစ်မျိုးကို တစ်လိုင်းသာ ထည့်ပါ။ ထပ်ထည့်ခွင့် အတည်ပြုရန်ကျန်သည်။');if(value('fBasis')==='bag'&&rows.some(x=>!(productStandard(x.product)>0)))return error('ကုန်ပစ္စည်း၏ စံအိတ်ဝင်ပိဿာ သတ်မှတ်ပါ။');if(net<0||paid<0||paid>net)return error('နုတ်ငွေ/ငွေရှင်းပမာဏကို ပြန်စစ်ပါ။');
