 if(!sale&&rows.some(x=>!state.lots.find(l=>l.receiptId===x.r.id&&l.owner==='supplier')||state.lots.filter(l=>l.receiptId===x.r.id).length!==1))return error('ကုန်လက်ခံအသုတ်ကို ဂိုဒေါင်အများအပြားသို့ ခွဲရွှေ့ထားပါသည်။ မူလဂိုဒေါင်သို့ ပြန်စုစည်းပြီး ဈေးဖြတ်ပါ။');
 const no=(sale?'အရ-':'အဝ-')+(++state.counter),ids=[],recs=[];let assignedDed=0;
