renderSaleRows=function(){const root=document.getElementById('saleRows');if(!root)return;const groups=group4(state.sales).filter(rs=>rs.some(s=>(s.name+s.product+s.no).toLowerCase().includes(searchTerm.toLowerCase()))).filter(rs=>filter==='all'||rs.some(s=>filter==='collect'?saleRemaining(s)>0:filter==='debt'?receivable(s)>0:filter==='delivered'?saleRemaining(s)===0:true));root.innerHTML=groups.map(rs=>{const r=rs[0],rem=rs.reduce((n,s)=>n+saleRemaining(s),0),d=rs.reduce((n,s)=>n+receivable(s),0);return `<article class="card mb"><div class="row between wrap"><div><h3>${E(r.name)}</h3><span class="small muted">${E(r.voucherNo||r.no)} · ${shortDate(r.date)}</span></div>${pill(rem?'ထုတ်ပေးရန်ကျန်':'ထုတ်ပေးပြီး',rem?'blue':'')}</div><div class="req-chip-row">${rs.map(s=>`<span>${E(s.product)} · ${vissText37(s.qty)} ပိဿာ · ${E(W(s.warehouse))}</span>`).join('')}</div><div class="row between wrap mt"><strong>ရရန် ${cashText(d)}</strong><div class="row wrap">${btn('အသေးစိတ်',`saleDetail4('${r.id}')`,'secondary','eye')}${d?btn('ငွေလက်ခံမယ်',`payVoucher4('sale','${r.id}')`,'primary','wallet')+smallbtn('တောင်းခံလက်မှတ်',`openSlip4('${r.id}')`,'secondary','print'):''}</div></div></article>`;}).join('')||empty('အရောင်းမှတ်တမ်း မရှိပါ။');};
function saleDetail4(id){const rs=voucherRecords4('sale',id),r=rs[0];if(!r)return;openModal('အရောင်းအသေးစိတ်',r.name+' · '+(r.voucherNo||r.no),table4(['ကုန် / အသုတ်','ဂိုဒေါင်','ပိဿာ','တန်ဖိုး','ကုန်ထုတ်'],rs.map(s=>`<tr><td>${E(s.product)}<div class="small muted">${E(s.batch||'—')}</div></td><td>${E(W(s.warehouse))}</td><td>${vissText37(s.qty)}</td><td>${cashText(s.total)}</td><td>${saleRemaining(s)>0?smallbtn('ထုတ်ပေးမယ်',`dispatch4('${s.id}')`,'primary'):pill('ထုတ်ပြီး')}</td></tr>`))+`<div class="summary-box mt">${row4('စုစုပေါင်း',cashText(rs.reduce((n,s)=>n+s.total,0)))}${row4('ရရန်ကျန်',cashText(rs.reduce((n,s)=>n+receivable(s),0)))}</div>`+(r.charges4?chargesSummary4(r.charges4):'')+`<h3 class="mt">ငွေပေးချေနည်းအလိုက် လက်ခံမှတ်တမ်း</h3>${paymentHistory(rs.flatMap(s=>s.payments||[]),false)}`,btn('ပြန်မယ်','closeModal()','secondary')+btn('ဘောက်ချာ Print',`printVoucher4('sale','${id}')`,'secondary','print')+(rs.some(s=>receivable(s)>0)?btn('ငွေလက်ခံမယ်',`payVoucher4('sale','${id}')`):''),true);}
