function printVoucher4(kind,id){const rs=voucherRecords4(kind,id),r=rs[0];printDocument(kind==='sale'?'အရောင်းဘောက်ချာ':'ကုန်လက်ခံ / အဝယ်ဘောက်ချာ',r.voucherNo||r.no,`<p>${E(r.name)} · ${shortDate(r.date)}</p>${kind==='purchase'&&r.car?`<p>ကားနံပါတ် — ${E(r.car)}</p>`:''}`+table4(['ကုန်','ပိဿာ','တန်ဖိုး'],rs.map(x=>`<tr><td>${E(x.product)}</td><td>${vissText37(x.qty)}</td><td>${cashText(kind==='sale'?x.total:gross(x))}</td></tr>`)));}
function dispatch4(id){if(!guardWork())return;const s=state.sales.find(s=>s.id===id);if(!s||saleRemaining(s)<=0)return;const lots=state.lots.filter(l=>l.saleId===id&&l.owner==='customer'&&l.qty>0);openModal('ဝယ်သူပိုင်ကုန် ထုတ်ပေးမယ်',s.name+' · '+s.product,`<form id="dispatch4" onsubmit="event.preventDefault();saveDispatch4('${id}')">${selectField('ဂိုဒေါင် / ဝယ်သူပိုင်အသုတ်','dLot',lots.map(l=>[l.id,`${W(l.warehouse)} · ${vissText37(l.qty)} ပိဿာ`]))}${num4('ထုတ်ပေးပိဿာ','dQty',saleRemaining(s),.001)}${date4()}</form>`,btn('ပြန်မယ်','closeModal()','secondary')+btn('ကုန်ထုတ် သိမ်းမယ်',`saveDispatch4('${id}')`));}
function saveDispatch4(id){if(!guardWork()||!validForm('dispatch4'))return;const s=state.sales.find(s=>s.id===id),l=state.lots.find(l=>l.id===value('dLot')),q=number('dQty');if(!l||l.saleId!==id||!(q>0)||q>l.qty+.000001||q>saleRemaining(s)+.000001)return error('ရွေးထားသောဂိုဒေါင်၏ ဝယ်သူပိုင်လက်ကျန် မလောက်ပါ။');takeLot4(l,q);s.deliveredQty+=q;s.deliveredBags=s.bags*(s.deliveredQty/s.qty);s.dispatches.push({date:value('fDate'),qty:q,warehouse:l.warehouse});dateMove(s.product,q,'out',s.no,value('fDate'),'dispatch');done4('ကုန်ထုတ်ပေးပြီးပါပြီ။','sales');}
