function stockRows4(){const wh=value('stockWh4')||'all',owner=value('stockOwner4')||'all',product=value('stockProduct78');return table4(['ကုန် / အသုတ်','ကုန်ဝင်ရက်','ဂိုဒေါင်','ပိုင်ဆိုင်မှု / ပိုင်ရှင်','ပုံစံ','ပိဿာ'],state.lots.filter(l=>(l.qty>0||l.weightKnown===false)&&(wh==='all'||l.warehouse===wh)&&(owner==='all'||l.owner===owner)&&(!product||l.product===product)).map(l=>`<tr><td><strong>${E(l.product)}</strong><div class="small muted">${E(l.batch)}</div></td><td>${shortDate(l.entryDate||today())}</td><td>${E(W(l.warehouse))}</td><td>${ownershipDefinitions.find(d=>d[0]===l.owner)?.[1]}<div class="small muted">${E(l.name)}</div></td><td>${l.stockForm==='packaged'?E(l.packName||'ထုပ်ပိုးပြီး')+' · '+vissText37(l.packageViss)+' ပိဿာ/အိတ်':'မထုပ်ပိုးရသေး'}</td><td><strong>${l.weightKnown===false?'မသိသေး':N(l.qty)}</strong></td></tr>`));}
