function editWarehouse4(id=''){if(state.role!=='owner')return;const w=state.warehouses.find(w=>w.id===id);openModal('ဂိုဒေါင် သတ်မှတ်မယ်','ဂိုဒေါင်အရေအတွက်ကို ကန့်သတ်မထားပါ။',`<form id="warehouseForm4" onsubmit="event.preventDefault();saveWarehouse4('${id}')">${field('ဂိုဒေါင်အမည်','wName',{value:w?.name||'',required:true})}${selectField('အခြေအနေ','wActive',[['yes','အသုံးပြုနေ'],['no','ပိတ်ထား']],w?.active===false?'no':'yes')}</form>`,btn('ပြန်မယ်','closeModal()','secondary')+btn('သိမ်းမယ်',`saveWarehouse4('${id}')`));}
function saveWarehouse4(id){if(!owner4()||!validForm('warehouseForm4'))return;const name=value('wName');if(!safeLabel(name)||state.warehouses.some(w=>w.name===name&&w.id!==id))return error('ဂိုဒေါင်အမည် မမှန်ပါ သို့မဟုတ် ထပ်နေပါသည်။');if(value('wActive')==='no'&&state.lots.some(l=>l.warehouse===id&&(l.qty>0||l.weightKnown===false)))return error('ကုန်လက်ကျန်ရှိသောဂိုဒေါင်ကို ပိတ်၍မရပါ။');const w=state.warehouses.find(w=>w.id===id);if(w)Object.assign(w,{name,active:value('wActive')==='yes'});else state.warehouses.push({id:uid('W'),name,active:true});audit4(name+' ဂိုဒေါင်သတ်မှတ်ချက် သိမ်းခဲ့သည်။');opsTab='warehouse';done4('ဂိုဒေါင် သိမ်းပြီးပါပြီ။','operations');}
function transfer4(){if(!guardWork())return;const opts=[...lotOpts('owned'),...lotOpts('supplier'),...lotOpts('customer')];if(!opts.length)return toast('ပြောင်းရွှေ့ရန် ကုန်မရှိပါ။',true);openModal('ဂိုဒေါင် ပြောင်းရွှေ့မယ်','ကုန်ပိုင်ရှင်၊ အဝယ်အသုတ်နှင့် ကုန်တန်ဖိုး ဆက်လက်ထိန်းထားမည်။',`<form id="transferForm4" onsubmit="event.preventDefault();saveTransfer4()">${selectField('မူလကုန် / ပိုင်ရှင် / အသုတ်','tLot',opts)}${selectField('လက်ခံဂိုဒေါင်','tWh',whOpts())}${num4('ပြောင်းရွှေ့ပိဿာ','tQty','',.001)}${date4()}</form>`,btn('ပြန်မယ်','closeModal()','secondary')+btn('ပြောင်းရွှေ့ သိမ်းမယ်','saveTransfer4()'));}
function saveTransfer4(){if(!guardWork()||!validForm('transferForm4'))return;const l=state.lots.find(l=>l.id===value('tLot')),wh=value('tWh'),qty=number('tQty');if(!l||wh===l.warehouse)return error('မူလဂိုဒေါင်နှင့် လက်ခံဂိုဒေါင် မတူရပါ။');if(!(qty>0)||qty>l.qty+.000001)return error('မူလအသုတ် လက်ကျန်မလောက်ပါ။');const before=l.qty,bags=(l.bags||0)*qty/before,to={...l,id:uid('L'),warehouse:wh,qty,bags,packageCount:l.packageViss?qty/l.packageViss:0};takeLot4(l,qty);state.lots.push(to);state.transfers.unshift({id:uid('TR'),date:value('fDate'),product:l.product,batch:l.batch,name:l.name,owner:l.owner,from:l.warehouse,to:wh,qty});audit4(l.product+' '+W(l.warehouse)+' မှ '+W(wh)+' သို့ ပြောင်းရွှေ့ခဲ့သည်။');invTab='transfers';done4('ဂိုဒေါင် ပြောင်းရွှေ့ပြီးပါပြီ။','inventory');}
openPackaging=function(){if(!guardWork())return;const opts=lotOpts('owned',true);if(!opts.length)return toast('ထုပ်ပိုးရန် ပွဲရုံပိုင်ကုန် မရှိပါ။',true);openModal('အဝယ်အသုတ်မှ ထုပ်ပိုးမယ်','ရွေးထားသောအသုတ်မှသာ လက်ကျန်လျော့မည်။',`<form id="packForm4" onsubmit="event.preventDefault();savePack4()">${selectField('ကုန် / ဂိုဒေါင် / အဝယ်အသုတ်','pkLot',opts,'','onchange="packOptions4()"')}<div id="pkTypeWrap"></div>${num4('ထုပ်ပိုးအိတ်အရေအတွက်','pkCount',1,1,'oninput="packPreview4()"')}${date4()}<div id="pkPreview" class="summary-box"></div></form>`,btn('ပြန်မယ်','closeModal()','secondary')+btn('ထုပ်ပိုး သိမ်းမယ်','savePack4()'),true);document.getElementById('pkCount').step='1';packOptions4();};
function packOptions4(){const l=state.lots.find(l=>l.id===value('pkLot'));document.getElementById('pkTypeWrap').innerHTML=selectField('ထုပ်ပိုးပုံစံ','pkType',state.packTypes.filter(p=>p.active&&p.product===l?.product).map(p=>[p.id,`${p.name} · ${N(p.size)} ${p.unit}`]),'','onchange="packPreview4()"');packPreview4();}
function packPreview4(){const l=state.lots.find(l=>l.id===value('pkLot')),p=state.packTypes.find(p=>p.id===value('pkType')),count=number('pkCount')||0;document.getElementById('pkPreview').innerHTML=p?row4('ထုပ်ပိုးမည့်ပိဿာ',vissText37(p.size*count))+row4('အသုတ်လက်ကျန်',vissText37(l.qty))+row4('ထုပ်ပိုးပြီးကျန်ပိဿာ',vissText37(l.qty-p.size*count)):note('ဤကုန်အတွက် အသုံးပြုနေသော ထုပ်ပိုးပုံစံ မရှိပါ။ ပိုင်ရှင်က သတ်မှတ်ပေးရန်လိုသည်။','amber');}
function savePack4(){if(!guardWork()||!validForm('packForm4'))return;const l=state.lots.find(l=>l.id===value('pkLot')),p=state.packTypes.find(p=>p.id===value('pkType')),count=number('pkCount'),q=(p?.size||0)*count;if(!l||!p?.active||p.product!==l.product||!Number.isInteger(count)||count<1||q>l.qty+.000001)return error('ထုပ်ပိုးပုံစံ / အရေအတွက် / အသုတ်လက်ကျန်ကို ပြန်စစ်ပါ။');const created={...l,id:uid('L'),qty:q,bags:count,packageCount:count,packageViss:p.size,stockForm:'packaged',packType:p.id,packName:p.name};takeLot4(l,q);state.lots.push(created);state.packagingTransactions.push({id:uid('PK'),date:value('fDate'),product:l.product,qty:q,bagCount:count,packageViss:p.size,type:'pack',warehouse:l.warehouse,batch:l.batch,sourceLot:l.id,packName:p.name});audit4(l.batch+' အသုတ်မှ '+p.name+' ထုပ်ပိုးခဲ့သည်။');opsTab='warehouse';done4('အသုတ်မှ ထုပ်ပိုးပြီးပါပြီ။','operations');}
function statements4(){return `<section class="card"><h3 class="mb">ကုန်သည် / ဝယ်သူ စာရင်းရှင်းတမ်း</h3><form id="statementForm4" onsubmit="event.preventDefault();renderStatement4()"><div class="field-row">${selectField('သက်ဆိုင်သူ','stParty',state.masters.partners.filter(p=>p.active).map(p=>[p.id,`${supplierLabel(p)} · ${p.kind==='buyer'?'ဝယ်သူ':'ကုန်သည်'}`]))}${field('မှ ရက်','stFrom',{type:'date',value:today().slice(0,8)+'01',required:true})}${field('ထိ ရက်','stTo',{type:'date',value:today(),required:true})}</div>${btn('စာရင်းရှင်းတမ်း ကြည့်မယ်','renderStatement4()','primary','doc')}</form><div id="statementBody4" class="mt">${note('သက်ဆိုင်သူနှင့် ရက်ကာလကို ရွေးပြီး ကြည့်ပါ။')}</div></section>`;}
function statementData4(pArg,fromArg,toArg){const p=pArg||supplierBy(value('stParty')),from=fromArg===undefined?value('stFrom'):fromArg,to=toArg===undefined?value('stTo'):toArg;if(!p||!from||!to||from>to)return null;const rs=state.receipts.filter(r=>r.partnerId===p.id),ss=state.sales.filter(s=>s.buyerId===p.id),adv=(state.partnerAdvances||[]).filter(a=>a.partnerId===p.id),all=[];
 rs.forEach(r=>{all.push({date:r.date,ref:r.voucherNo||r.no,type:'ကုန်ဝင်',product:r.product,qty:receiptReceivedQuantity2(r)});if(r.status==='purchased')all.push({date:r.purchaseDate||r.date,ref:r.purchaseNo||r.no,type:'အဝယ်',payable:purchaseNet(r)});(r.payments||[]).forEach(a=>all.push({date:a.date,ref:r.no,type:'ငွေပေး · '+(ACCOUNT_NAMES[a.account]||a.account),payable:-a.amount}));});
 ss.forEach(s=>{all.push({date:s.date,ref:s.voucherNo||s.no,type:'အရောင်း',product:s.product,qty:s.qty,receivable:s.total});(s.payments||[]).forEach(a=>all.push({date:a.date,ref:s.no,type:'ငွေလက်ခံ · '+(ACCOUNT_NAMES[a.account]||a.account),receivable:-a.amount}));(s.dispatches||[]).forEach(d=>all.push({date:d.date,ref:s.no,type:'ကုန်ထုတ်',product:s.product,qty:-d.qty}));if(s.mode==='direct')all.push({date:s.date,ref:s.no,type:'ကုန်ထုတ်',product:s.product,qty:-s.qty});});
adv.forEach(a=>{all.push({date:a.date,ref:a.id,type:'ကြိုသုံးငွေ',advance:a.amount});(a.allocations||[]).forEach(x=>all.push({date:x.date||a.date,ref:a.id,type:'ကြိုငွေပြန်နုတ်',advance:-x.amount}));});
 all.sort((a,b)=>a.date.localeCompare(b.date));const opening=all.filter(x=>x.date<from),selected=all.filter(x=>x.date>=from&&x.date<=to),sum=(rows,k)=>rows.reduce((n,x)=>n+(x[k]||0),0);return {p,from,to,opening,selected,sum};}
function renderStatement4(){if(!validForm('statementForm4'))return;const d=statementData4();if(!d)return toast('ရက်ကာလကို မှန်ကန်စွာရွေးပါ။',true);let pay=d.sum(d.opening,'payable'),recv=d.sum(d.opening,'receivable'),advance=d.sum(d.opening,'advance');const opening={pay,recv,advance};document.getElementById('statementBody4').innerHTML=`<div class="summary-box mb">${row4('ကာလအစ ပေးရန်',cashText(pay))}${row4('ကာလအစ ရရန်',cashText(recv))}${row4('ကာလအစ ကြိုငွေ',cashText(advance))}</div>`+table4(['ရက် / အမှတ်','အကြောင်းအရာ','ကုန် / ပိဿာ','ပေးရန်လက်ကျန်','ရရန်လက်ကျန်','ကြိုငွေလက်ကျန်'],d.selected.map(x=>{pay+=x.payable||0;recv+=x.receivable||0;advance+=x.advance||0;return `<tr><td>${shortDate(x.date)}<div class="small muted">${E(x.ref)}</div></td><td>${E(x.type)}</td><td>${E(x.product||'—')} ${x.qty!==undefined?' · '+N(x.qty):''}</td><td>${cashText(pay)}</td><td>${cashText(recv)}</td><td>${cashText(advance)}</td></tr>`;}))+`<div class="summary-box mt">${row4('ကာလပိတ် ပေးရန်',cashText(pay))}${row4('ကာလပိတ် ရရန်',cashText(recv))}${row4('ကာလပိတ် ကြိုငွေ',cashText(advance))}</div><div class="mt">${btn('စာရင်းရှင်းတမ်း Print','printStatement4()','secondary','print')}</div>`;}
function printStatement4(){const d=statementData4();if(d)printDocument('စာရင်းရှင်းတမ်း',d.p.name,`<p>${shortDate(d.from)} – ${shortDate(d.to)}</p>`+document.getElementById('statementBody4').innerHTML.replace(/<button[\s\S]*?<\/button>/g,''));}
/* Collection slips cannot post cash before receipt. */
function collections4(){return `<section class="card"><h3>ရရန်ငွေကျန်သော အရောင်းများ</h3>${table4(['ဝယ်သူ / ဘောက်ချာ','ရရန်ကျန်','လုပ်ဆောင်ရန်'],group4(state.sales).filter(rs=>rs.some(s=>receivable(s)>0)).map(rs=>`<tr><td>${E(rs[0].name)} · ${E(rs[0].voucherNo||rs[0].no)}</td><td>${cashText(rs.reduce((n,s)=>n+receivable(s),0))}</td><td>${btn('တောင်းခံလက်မှတ် ထုတ်မယ်',`openSlip4('${rs[0].id}')`,'secondary','print')}</td></tr>`))}</section><section class="card mt"><h3>တောင်းခံလက်မှတ် မှတ်တမ်း</h3>${table4(['လက်မှတ် / ရက်','ဝယ်သူ','တောင်းခံပမာဏ','ရရှိငွေ','အခြေအနေ','လုပ်ဆောင်ရန်'],state.collectionSlips.map(s=>`<tr><td>${E(s.no)}<div class="small muted">${shortDate(s.date)}</div></td><td>${E(s.name)}</td><td>${cashText(s.amount)}</td><td>${cashText(s.received||0)}</td><td>${pill((s.received||0)>=s.amount?'လက်ခံပြီး':s.received?'တစ်စိတ်တစ်ပိုင်း':'မရသေး',(s.received||0)>=s.amount?'':'amber')}</td><td><div class="row wrap">${smallbtn('Print',`printSlip4('${s.id}')`,'secondary','print')}${(s.received||0)<s.amount?smallbtn('ငွေသိမ်းမည်',`payVoucher4('sale','${s.saleId}','${s.id}')`,'primary'):''}</div></td></tr>`))}</section>`;}
function openSlip4(id){if(!guardWork())return;const rs=voucherRecords4('sale',id),d=rs.reduce((n,s)=>n+receivable(s),0);if(!(d>0))return toast('ရရန်ငွေ မကျန်ပါ။',true);openModal('အရောင်းကျန်ငွေ တောင်းခံလက်မှတ်','လက်မှတ်ထုတ်ရုံဖြင့် ငွေစာရင်းမပြောင်းပါ။',`<div class="summary-box mb">${row4('ဝယ်သူ',E(rs[0].name))}${row4('အရောင်းအမှတ်',E(rs[0].voucherNo||rs[0].no))}${row4('ရရန်ကျန်',cashText(d))}</div><form id="slipForm4" onsubmit="event.preventDefault();saveSlip4('${id}')">${date4()}${num4('တောင်းခံပမာဏ','slipAmount',d,.001)}</form>`,btn('ပြန်မယ်','closeModal()','secondary')+btn('လက်မှတ် သိမ်းမယ်',`saveSlip4('${id}')`));}
function saveSlip4(id){if(!guardWork()||!validForm('slipForm4'))return;const rs=voucherRecords4('sale',id),amount=number('slipAmount'),d=rs.reduce((n,s)=>n+receivable(s),0),outstanding=state.collectionSlips.filter(s=>voucherRecords4('sale',s.saleId)[0]?.id===rs[0].id).reduce((n,s)=>n+Math.max(0,s.amount-(s.received||0)),0);if(!(amount>0)||amount>d||amount+outstanding>d+.001)return error('တောင်းခံပမာဏသည် မတောင်းခံရသေးသော ရရန်ကျန်ထက် မပိုရပါ။');const slip={id:uid('CS'),no:'တခ-'+state.counter,date:value('fDate'),saleId:rs[0].id,name:rs[0].name,amount,received:0};state.collectionSlips.unshift(slip);audit4(slip.no+' တောင်းခံလက်မှတ် ထုတ်ခဲ့သည်။ ငွေစာရင်း မပြောင်းပါ။');opsTab='collections';done4('တောင်းခံလက်မှတ် သိမ်းပြီးပါပြီ။ ငွေစာရင်း မပြောင်းပါ။','operations');}
function printSlip4(id){const s=state.collectionSlips.find(s=>s.id===id),r=state.sales.find(r=>r.id===s?.saleId);if(!s||!r)return;printDocument('ငွေတောင်းခံလက်မှတ်',s.no,`<p>ဝယ်သူ — ${E(s.name)}</p><p>အရောင်းအမှတ် — ${E(r.voucherNo||r.no)}</p><p>ရက်စွဲ — ${shortDate(s.date)}</p><h2>တောင်းခံငွေ — ${cashText(s.amount)}</h2><p>ငွေလက်ခံပြီးကြောင်း လက်မှတ် မဟုတ်ပါ။</p>`);}
function settings4(){return `<section class="card"><div class="row between mb"><h3>ထုပ်ပိုးပုံစံ သတ်မှတ်ချက်</h3>${(state.role==='owner'||state.role==='staff')?btn('ပုံစံအသစ်','editPackType4()','secondary','plus'):''}</div>${table4(['ကုန်','ထုပ်ပိုးပုံစံ','တစ်ထုပ်ဝင်','အခြေအနေ','လုပ်ဆောင်ရန်'],state.packTypes.map(p=>`<tr><td>${E(p.product)}</td><td>${E(p.name)}</td><td>${N(p.size)} ${E(p.unit)}</td><td>${pill(p.active?'အသုံးပြုနေ':'ပိတ်ထား',p.active?'':'gray')}</td><td>${(state.role==='owner'||state.role==='staff')?smallbtn('ပြင်',`editPackType4('${p.id}')`,'secondary'):''}</td></tr>`))}</section><section class="card mt"><h3>ငွေပေးချေနည်းများ</h3>${table4(['အမည်','လက်ကျန်','အခြေအနေ'],state.masters.accounts.filter(a=>a.type!=='home'&&canViewAccount68(a)).map(a=>`<tr><td>${E(a.name)}</td><td>${cashText(bal(a.id))}</td><td>${pill(a.active?'အသုံးပြုနေ':'ပိတ်ထား',a.active?'':'gray')}</td></tr>`))}${state.role==='owner'?btn('ငွေပေးချေနည်း စီမံမယ်',"beginSetup('accounts')",'secondary'):''}</section><section class="card mt"><h3 class="mb">ကြိုထုတ်ငွေ အတိုးသတ်မှတ်ချက်</h3>${note('၃ ကျပ်/၄ ကျပ်နှုန်း အဓိပ္ပါယ်နှင့် လပြည့်/ရက်အလိုက်တွက်နည်း အတည်ပြုရန်ကျန်သည်။ အောက်တွင် လစဉ်ရာခိုင်နှုန်း မူကြမ်းအဖြစ်သာ သိမ်းမည်။ ငွေစာရင်းသို့ အလိုအလျောက် မတင်ပါ။','amber')}<form id="interestForm4" onsubmit="event.preventDefault();saveInterest4()"><div class="field-row mt">${selectField('ပွဲရုံ အတိုးမူဝါဒ','inEnabled',[['no','အတိုး မယူ'],['yes','အတိုး ယူ']],state.interestPolicy.enabled?'yes':'no')}${selectField('ကုန်သည်','inParty',partners('supplier').map(p=>[p.id,supplierLabel(p)]),'','onchange="loadInterest4()"')}</div>${num4('လစဉ် အတိုးရာခိုင်နှုန်း မူကြမ်း','inRate',0,0)}${state.role==='owner'?btn('မူဝါဒမူကြမ်း သိမ်းမယ်','saveInterest4()','secondary'):''}</form></section>`;}
function editPackType4(id=''){if(state.role!=='owner')return;const p=state.packTypes.find(p=>p.id===id);openModal('ထုပ်ပိုးပုံစံ သတ်မှတ်မယ်','ပိတ်ထားသောပုံစံကို ထုပ်ပိုးမှုအသစ်တွင် မရွေးနိုင်ပါ။',`<form id="packTypeForm4" onsubmit="event.preventDefault();savePackType4('${id}')">${selectField('ကုန်ပစ္စည်း','ptProduct',pOpts(),p?.product||'')}${field('ထုပ်ပိုးပုံစံအမည်','ptName',{value:p?.name||'',required:true})}${num4('တစ်ထုပ်ဝင် ပိဿာ','ptSize',p?.size||'',.001)}${selectField('အခြေအနေ','ptActive',[['yes','အသုံးပြုနေ'],['no','ပိတ်ထား']],p?.active===false?'no':'yes')}</form>`,btn('ပြန်မယ်','closeModal()','secondary')+btn('သိမ်းမယ်',`savePackType4('${id}')`));}
function savePackType4(id){if(!owner4()||!validForm('packTypeForm4'))return;const name=value('ptName'),product=value('ptProduct'),size=number('ptSize');if(!safeLabel(name)||!(size>0)||state.packTypes.some(p=>p.product===product&&p.name===name&&p.id!==id))return error('ပုံစံအမည် ထပ်နေပါသည် သို့မဟုတ် ပမာဏ မမှန်ပါ။');const p=state.packTypes.find(p=>p.id===id),obj={product,name,size,unit:'ပိဿာ',active:value('ptActive')==='yes'};if(p)Object.assign(p,obj);else state.packTypes.push({id:uid('PT'),...obj});audit4(name+' ထုပ်ပိုးပုံစံ သိမ်းခဲ့သည်။');opsTab='settings';done4('ထုပ်ပိုးပုံစံ သိမ်းပြီးပါပြီ။','operations');}
function loadInterest4(){document.getElementById('inRate').value=state.interestPolicy.rates[value('inParty')]||0;}
function saveInterest4(){if(!owner4()||!validForm('interestForm4'))return;const rate=number('inRate');if(rate<0||rate>100)return error('အတိုးရာခိုင်နှုန်းကို ပြန်စစ်ပါ။');state.interestPolicy.enabled=value('inEnabled')==='yes';state.interestPolicy.rates[value('inParty')]=rate;audit4('ကြိုထုတ်ငွေ အတိုးသတ်မှတ်ချက် မူကြမ်းသိမ်းခဲ့သည်။');done4('အတိုးမူဝါဒ မူကြမ်းသိမ်းပြီးပါပြီ။','operations');}
