function ensureDeductionRateMasters(){
 state.masters??={};
 const legacy=state.masters.purchaseDeductions||{workRate:0,laborRate:0};
 if(!Array.isArray(state.masters.purchaseDeductionRates))state.masters.purchaseDeductionRates=[];
 /* V4.2 migration: remove the previously auto-seeded deduction rates. From now on every rate is user-created CRUD master data. */
 if(!state.masters.purchaseDeductionRatesManualOnly){
  const seededIds=new Set(['DR-S-BAG','DR-S-PCT-1','DR-S-PCT-2','DR-S-PCT-3','DR-S-PCT-4','DR-S-PCT-5','DR-S-PCT-6','DR-L-BAG']);
  state.masters.purchaseDeductionRates=state.masters.purchaseDeductionRates.filter(r=>!seededIds.has(r.id));
  state.masters.purchaseDeductionRatesManualOnly=true;
 }
 state.masters.purchaseDeductions=legacy;
}
const deductionInitBase=initV4;
