function deductionRates(kind,activeOnly=false){ensureDeductionRateMasters();return state.masters.purchaseDeductionRates.filter(r=>r.kind===kind&&(!activeOnly||r.active));}
function deductionBasisLabel(r){return r.basis==='percent_total'?'စုစုပေါင်းတန်ဖိုး၏ '+N(r.rate)+'%':'တစ်အိတ် '+cashText(r.rate);}
