function rateAmount(rule,gross,bags){if(!rule||!rule.active)return 0;return Math.round(rule.basis==='percent_total'?gross*(Number(rule.rate)||0)/100:bags*(Number(rule.rate)||0));}
function rateUsed(id){return [...state.receipts,...state.sales].some(r=>r.serviceRateId===id||r.laborDeductionRateId===id||r.charges4?.serviceRateId===id||r.charges4?.laborDeductionRateId===id);}
