pricingCalc=function(id){
 const r=state.receipts.find(x=>x.id===id);if(!r)return null;const price=number('receiptPrice')||0,bags=pricingBagCount(r),gross=Math.round(bags*price);
 const serviceRule=deductionRateById(value('purchaseServiceRate'))||defaultDeductionRate('service'),laborRule=deductionRateById(value('purchaseLaborRate'))||defaultDeductionRate('labor');
 const work=rateAmount(serviceRule,gross,bags),labor=rateAmount(laborRule,gross,bags),beforeAdvance=Math.max(0,gross-work-labor),pool=supplierBalance(r.partnerId),advance=Math.min(pool,beforeAdvance);
 return {r,price,bags,gross,serviceRule,laborRule,work,labor,pool,advance,net:beforeAdvance-advance,workRate:Number(serviceRule?.rate)||0,laborRate:Number(laborRule?.rate)||0};
};
