updatePricingSheet=function(id){const c=pricingCalc(id),box=document.getElementById('pricingSheet');if(!c||!box)return;box.innerHTML=!(c.price>0)?note('တစ်အိတ် ဝယ်ဈေး ထည့်ပါ။','amber'):`<div class="summary-line"><span>ကုန်ဖိုး (${N(c.bags)} အိတ် × ${M(c.price)})</span><strong>${cashText(c.gross)}</strong></div><div class="summary-line"><span>ဝန်ဆောင်ခ · ${E(deductionBasisLabel(c.serviceRule||{}))}</span><strong>− ${cashText(c.work)}</strong></div><div class="summary-line"><span>လုပ်သားခ · ${E(deductionBasisLabel(c.laborRule||{}))}</span><strong>− ${cashText(c.labor)}</strong></div><div class="summary-line"><span>ကြိုတင်ယူငွေ</span><strong>− ${cashText(c.advance)}</strong></div><div class="summary-line total"><span>အသားတင် ရငွေ</span><strong>${cashText(c.net)}</strong></div>`;};
