commitPriceVoucher=function(id){const c=pricingCalc(id);if(c?.r){c.r.serviceRateId=c.serviceRule?.id||'';c.r.serviceRateBasis=c.serviceRule?.basis||'';c.r.serviceRateValue=c.serviceRule?.rate||0;c.r.laborDeductionRateId=c.laborRule?.id||'';c.r.laborRateBasis=c.laborRule?.basis||'';c.r.laborRateValue=c.laborRule?.rate||0;}deductionCommitPriceBase(id);};
const deductionPrintPriceBase=printPriceVoucher;
printPriceVoucher=function(id){const r=state.receipts.find(x=>x.id===id);if(!r)return deductionPrintPriceBase(id);const sr=deductionRateById(r.serviceRateId),lr=deductionRateById(r.laborDeductionRateId);document.getElementById('printArea').innerHTML=`<div class="print-title"><h1>အဝယ်ဘောက်ချာ</h1><p>${E(r.purchaseNo||r.no)} · ${shortDate(r.purchaseDate||r.date)}</p></div><p>ကုန်သည် — <strong>${E(r.name)}</strong></p><p>ကုန် — <strong>${E(r.product)} · ဝယ်ဈေးတန်း ${E(r.grade)}</strong></p><table style="margin-top:18px"><thead><tr><th>အလေးချိန်</th><th>အိတ်ဖွဲ့စည်းပုံ</th><th>တစ်အိတ်ဈေး</th><th>ကုန်ဖိုး</th></tr></thead><tbody><tr><td>${vissText37(r.qty)} ပိဿာ</td><td>${E(standardComposition(r.product,r.qty))}</td><td>${cashText(r.price)}</td><td>${cashText(gross(r))}</td></tr></tbody></table><p>ဝန်ဆောင်ခ${sr?' · '+E(deductionBasisLabel(sr)):''} — − ${cashText(r.wage||0)}</p><p>လုပ်သားခ${lr?' · '+E(deductionBasisLabel(lr)):''} — − ${cashText(r.weigh||0)}</p><p>ကြိုတင်ယူငွေ — − ${cashText(r.advance||0)}</p><h2>အသားတင် — ${cashText(purchaseNet(r))}</h2>`;window.print();};

/* The multi-product purchase voucher also uses the same service-fee master. */
const deductionChargesFormBase=chargesForm4;
chargesForm4=function(){let html=deductionChargesFormBase();if(v4Kind!=='purchase')return html;const opts=deductionRates('service',true),selected=opts[0]?.id||'';const control=`<div class="field mt">${selectField('ဝန်ဆောင်ခနှုန်းထား','fServiceRate',[['','မရွေးပါ'],...opts.map(r=>[r.id,deductionOptionLabel(r)])],selected,'onchange="calcVoucher4()"')}</div>`;return html.replace('<div class="row between wrap mt"><h3>အိတ်ဆိုဒ်အလိုက် လုပ်သားခ</h3></div>',control+'<div class="row between wrap mt"><h3>အိတ်ဆိုဒ်အလိုက် လုပ်သားခ</h3></div>');};
const deductionReadChargesBase=readCharges4;
readCharges4=function(){const c=deductionReadChargesBase();if(v4Kind==='purchase'&&document.getElementById('fServiceRate')){const rows=readVoucherLines4(),gross=rows.reduce((n,r)=>n+r.total,0),bags=rows.reduce((n,r)=>n+(productStandard(r.product)?r.qty/productStandard(r.product):0),0),rule=deductionRateById(value('fServiceRate'));c.serviceRateId=rule?.id||'';c.serviceRateBasis=rule?.basis||'';c.serviceRateValue=rule?.rate||0;c.serviceFee=rateAmount(rule,gross,bags);}else c.serviceFee=0;return c;};
const deductionCalcVoucherBase=calcVoucher4;
calcVoucher4=function(){deductionCalcVoucherBase();if(v4Kind!=='purchase')return;const root=document.getElementById('voucherSummary4');if(!root)return;const rows=readVoucherLines4(),c=readCharges4(),gross=rows.reduce((n,r)=>n+r.total,0),deductions=c.truck+c.labor+c.clean+c.plastic+c.sack+c.advance+(c.serviceFee||0),net=gross-deductions,paid=number('fPaid')||0,rule=deductionRateById(c.serviceRateId);root.innerHTML=row4('စုစုပေါင်းကုန်ဖိုး',cashText(gross))+row4('ဝန်ဆောင်ခ'+(rule?' · '+deductionBasisLabel(rule):''),cashText(c.serviceFee||0))+row4('အလုပ်သမားခ',cashText(c.labor))+row4('စုစုပေါင်းနုတ်ငွေ',cashText(deductions))+row4('အသားတင်',cashText(net))+row4('ယခုငွေရှင်း',cashText(paid))+row4('ပေးရန်ကျန်',cashText(net-paid))+`<p class="small muted mt">ဝန်ဆောင်ခနှုန်းကို အဝယ် နုတ်ငွေ နှုန်းထား Master မှ ရွေးချယ်ထားသည်။</p>`;};
const deductionChargesSummaryBase=chargesSummary4;
chargesSummary4=function(c){let html=deductionChargesSummaryBase(c);if(c?.serviceFee){const r=deductionRateById(c.serviceRateId);html=html.replace('<div class="summary-box">','<div class="summary-box">'+row4('ဝန်ဆောင်ခ'+(r?' · '+deductionBasisLabel(r):''),cashText(c.serviceFee)));}return html;};
